import{_ as s,C as i,o as l,c as r,j as e,a as o,E as n,a3 as c}from"./chunks/framework.CJlOecQn.js";const m=JSON.parse('{"title":"First 30 days checklist","description":"A printable checklist for your first month in Qatar, with a link to the sourced guide page behind each step.","frontmatter":{"title":"First 30 days checklist","description":"A printable checklist for your first month in Qatar, with a link to the sourced guide page behind each step.","aside":false},"headers":[],"relativePath":"checklist.md","filePath":"checklist.md"}'),d={name:"checklist.md"};function k(h,a,u,b,f,p){const t=i("ChecklistTools");return l(),r("div",null,[a[0]||(a[0]=e("h1",{id:"first-30-days-in-qatar",tabindex:"-1"},[o("First 30 days in Qatar "),e("a",{class:"header-anchor",href:"#first-30-days-in-qatar","aria-label":'Permalink to "First 30 days in Qatar"'},"​")],-1)),a[1]||(a[1]=e("p",null,"A printable list of the steps most new residents have to work through. Each item links to the guide page that gives the details and the official sources. Your situation may differ, so check the linked page before you act.",-1)),n(t),a[2]||(a[2]=c('<h2 id="before-you-travel" tabindex="-1">Before you travel <a class="header-anchor" href="#before-you-travel" aria-label="Permalink to &quot;Before you travel&quot;">​</a></h2><ul class="task-list"><li class="task-item"><input type="checkbox" class="task-box" id="task-1" data-task="task-1"><label for="task-1" class="task-label">Check your passport. Two Ministry of Interior pages differ on how long it must stay valid, so aim for the longer period. <a href="./guide/arriving-and-visas">Arriving and visas</a></label></li><li class="task-item"><input type="checkbox" class="task-box" id="task-2" data-task="task-2"><label for="task-2" class="task-label">If you are coming to work, gather what the work visa asks for, including your attested certificates and a good conduct certificate. <a href="./guide/arriving-and-visas">Arriving and visas</a></label></li><li class="task-item"><input type="checkbox" class="task-box" id="task-3" data-task="task-3"><label for="task-3" class="task-label">If your family will join you later, read what family residence needs before you leave home. <a href="./guide/family-visas">Family visas</a></label></li></ul><h2 id="your-first-days" tabindex="-1">Your first days <a class="header-anchor" href="#your-first-days" aria-label="Permalink to &quot;Your first days&quot;">​</a></h2><ul class="task-list"><li class="task-item"><input type="checkbox" class="task-box" id="task-4" data-task="task-4"><label for="task-4" class="task-label">Save 999 and the other emergency numbers in your phone. <a href="./guide/emergencies">Emergencies</a></label></li><li class="task-item"><input type="checkbox" class="task-box" id="task-5" data-task="task-5"><label for="task-5" class="task-label">Get a SIM, and bring your original QID, GCC ID or passport. <a href="./guide/phone-and-internet">Phone and internet</a></label></li><li class="task-item"><input type="checkbox" class="task-box" id="task-6" data-task="task-6"><label for="task-6" class="task-label">Keep a copy of your signed work contract. <a href="./guide/work-and-labour-rights">Work and labour rights</a></label></li><li class="task-item"><input type="checkbox" class="task-box" id="task-7" data-task="task-7"><label for="task-7" class="task-label">Learn how the metro, buses and taxis work. <a href="./guide/transport">Getting around</a></label></li></ul><h2 id="within-30-days-of-entering-qatar" tabindex="-1">Within 30 days of entering Qatar <a class="header-anchor" href="#within-30-days-of-entering-qatar" aria-label="Permalink to &quot;Within 30 days of entering Qatar&quot;">​</a></h2><ul class="task-list"><li class="task-item"><input type="checkbox" class="task-box" id="task-8" data-task="task-8"><label for="task-8" class="task-label">Do the medical checkup. If you entered on a residence visa, it must be done within thirty days of entry. <a href="./guide/residence-permit-and-qid">Residence permit and QID</a></label></li><li class="task-item"><input type="checkbox" class="task-box" id="task-9" data-task="task-9"><label for="task-9" class="task-label">Have your fingerprints taken after the medical. <a href="./guide/residence-permit-and-qid">Residence permit and QID</a></label></li><li class="task-item"><input type="checkbox" class="task-box" id="task-10" data-task="task-10"><label for="task-10" class="task-label">Prepare the documents for your sponsorship type, and submit them at an MOI Services Centre or Expatriate Affairs. <a href="./guide/residence-permit-and-qid">Residence permit and QID</a></label></li></ul><h2 id="once-you-have-your-qid" tabindex="-1">Once you have your QID <a class="header-anchor" href="#once-you-have-your-qid" aria-label="Permalink to &quot;Once you have your QID&quot;">​</a></h2><ul class="task-list"><li class="task-item"><input type="checkbox" class="task-box" id="task-11" data-task="task-11"><label for="task-11" class="task-label">Subscribe to Metrash alerts for expiry dates and traffic violations, and look at what the Metrash2 app can do. <a href="./guide/metrash">Metrash</a></label></li><li class="task-item"><input type="checkbox" class="task-box" id="task-12" data-task="task-12"><label for="task-12" class="task-label">Apply for a health card and find your health centre. Call PHCC on 107 first to confirm the current steps. <a href="./guide/health">Health care and insurance</a></label></li><li class="task-item"><input type="checkbox" class="task-box" id="task-13" data-task="task-13"><label for="task-13" class="task-label">Open a bank account, and ask the bank for its current list of documents. <a href="./guide/banking-and-money">Banking and money transfers</a></label></li><li class="task-item"><input type="checkbox" class="task-box" id="task-14" data-task="task-14"><label for="task-14" class="task-label">Check that your salary reaches your account on time. <a href="./guide/work-and-labour-rights">Work and labour rights</a></label></li></ul><h2 id="your-home" tabindex="-1">Your home <a class="header-anchor" href="#your-home" aria-label="Permalink to &quot;Your home&quot;">​</a></h2><ul class="task-list"><li class="task-item"><input type="checkbox" class="task-box" id="task-15" data-task="task-15"><label for="task-15" class="task-label">Read the lease section before you sign, and get your lease&#39;s RNR number, which Kahramaa asks for. <a href="./guide/housing-and-utilities">Housing and renting</a></label></li><li class="task-item"><input type="checkbox" class="task-box" id="task-16" data-task="task-16"><label for="task-16" class="task-label">Open your Kahramaa account through the Move to New Premises service. <a href="./guide/housing-and-utilities">Housing and renting</a></label></li><li class="task-item"><input type="checkbox" class="task-box" id="task-17" data-task="task-17"><label for="task-17" class="task-label">Set up home internet. <a href="./guide/phone-and-internet">Phone and internet</a></label></li></ul><h2 id="before-the-month-ends" tabindex="-1">Before the month ends <a class="header-anchor" href="#before-the-month-ends" aria-label="Permalink to &quot;Before the month ends&quot;">​</a></h2><ul class="task-list"><li class="task-item"><input type="checkbox" class="task-box" id="task-18" data-task="task-18"><label for="task-18" class="task-label">If you plan to drive, read the rules for foreign licences. <a href="./guide/driving">Driving</a></label></li><li class="task-item"><input type="checkbox" class="task-box" id="task-19" data-task="task-19"><label for="task-19" class="task-label">If you have children, start looking at schools. <a href="./guide/education">Education and schools</a></label></li><li class="task-item"><input type="checkbox" class="task-box" id="task-20" data-task="task-20"><label for="task-20" class="task-label">Write down the expiry dates of your residence permit and passport. <a href="./guide/residence-permit-and-qid">Residence permit and QID</a></label></li><li class="task-item"><input type="checkbox" class="task-box" id="task-21" data-task="task-21"><label for="task-21" class="task-label">Check the public holidays and Ramadan working hours that apply to you. <a href="./guide/holidays-and-ramadan">Holidays and Ramadan</a></label></li></ul><div class="warning custom-block"><p class="custom-block-title">Not legal advice</p><p>This list is a memory aid. The rules are on the official pages cited in each guide page, and they can change.</p></div><p>Ticks are saved only in this browser. Nothing is sent anywhere.</p>',14))])}const g=s(d,[["render",k]]);export{m as __pageData,g as default};
